const plainObj=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
const exactKeys=(x,keys)=>plainObj(x)&&Object.keys(x).length===keys.length&&keys.every(k=>k in x);
const shareEnvelopeV=(x,v)=>plainObj(x)&&Object.keys(x).sort().join(',')==='ciphertext,iv,version'&&x.version===v&&canonicalBase64Url(x.iv,12,12)&&canonicalBase64Url(x.ciphertext,17,MAX_SHARE_CIPHERTEXT);
const ownerNoteEnvelopeV=x=>plainObj(x)&&Object.keys(x).sort().join(',')==='ciphertext,iv,version'&&x.version===1&&typeof x.iv==='string'&&/^(?:[A-Za-z0-9+/]{16}|[A-Za-z0-9+/]{16}={0,2})$/.test(x.iv)&&typeof x.ciphertext==='string'&&/^[A-Za-z0-9+/]+={0,2}$/.test(x.ciphertext)&&x.ciphertext.length<=4096;
const passwordHash=(p,s=randomBytes(16))=>({salt:s.toString('base64'),hash:scryptSync(p,s,32,{N:32768,maxmem:64*1024*1024}).toString('base64')});
function verify(p,u){try{const a=scryptSync(p,Buffer.from(u.password_salt,'base64'),32,{N:32768,maxmem:64*1024*1024}),b=Buffer.from(u.password_hash,'base64');return a.length===b.length&&timingSafeEqual(a,b)}catch{return false}}
const CSP="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data: blob:; media-src 'self' blob:; frame-src 'self' blob:; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'";
const SECURITY_HEADERS={'x-content-type-options':'nosniff','x-frame-options':'DENY','referrer-policy':'no-referrer','permissions-policy':'camera=(), microphone=(), geolocation=(), payment=(), usb=()','content-security-policy':CSP};
const json=(res,status,value,headers={})=>{res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...SECURITY_HEADERS,...headers});res.end(status===204?'':JSON.stringify(value))};
function requireJson(req){if(String(req.headers['content-type']||'').split(';',1)[0].trim().toLowerCase()!=='application/json')throw Object.assign(new Error('unsupported_media_type'),{status:415})}
async function body(req){requireJson(req);let size=0,chunks=[];for await(const c of req){size+=c.length;if(size>MAX_BODY)throw Object.assign(new Error('too_large'),{status:413});chunks.push(c)}try{return JSON.parse(Buffer.concat(chunks).toString()||'{}')}catch{throw Object.assign(new Error('invalid_json'),{status:400})}}
async function backupBody(req){requireJson(req);let size=0,chunks=[];for await(const c of req){size+=c.length;if(size>MAX_BACKUP_JSON)throw Object.assign(new Error('too_large'),{status:413});chunks.push(c)}try{return JSON.parse(Buffer.concat(chunks).toString()||'{}')}catch{throw Object.assign(new Error('invalid_json'),{status:400})}}
const validWrapped=validWrappedKey;
const validPassword=x=>typeof x==='string'&&x.length>=1&&x.length<=1024;
function requestOrigin(req){const proto=(req.headers['x-forwarded-proto']||'').split(',')[0].trim()||'http';return `${proto}://${req.headers.host}`}
function sameOrigin(req){return req.headers.origin===requestOrigin(req)}
function csrf(req,s){const supplied=req.headers['x-csrf-token'];return typeof supplied==='string'&&digest(supplied)===s.csrf_hash&&req.headers.origin===requestOrigin(req)}
function auth(req){db.prepare('DELETE FROM sessions WHERE expires_at<=?').run(Date.now());const raw=(req.headers.cookie||'').split(';').map(v=>v.trim().split('=')).find(v=>v[0]===cookieName)?.[1];if(!raw)return null;return db.prepare('SELECT s.*,u.username FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.id_hash=? AND s.expires_at>?').get(digest(raw),Date.now())||null}
function limited(key,{record=true}={}){const now=Date.now();db.prepare('DELETE FROM auth_attempts WHERE attempted_at<?').run(now-60_000);const count=db.prepare('SELECT COUNT(*) count FROM auth_attempts WHERE key=? AND attempted_at>?').get(key,now-60_000).count;if(record)db.prepare('INSERT INTO auth_attempts VALUES(?,?)').run(key,now);return count>=10}
function takeRateSlot(key){const now=Date.now();db.exec('BEGIN IMMEDIATE');try{db.prepare('DELETE FROM auth_attempts WHERE attempted_at<?').run(now-60_000);const count=db.prepare('SELECT COUNT(*) count FROM auth_attempts WHERE key=? AND attempted_at>?').get(key,now-60_000).count;if(count>=10){db.exec('ROLLBACK');return null}let slot=now;while(db.prepare('SELECT 1 FROM auth_attempts WHERE key=? AND attempted_at=?').get(key,slot))slot++;db.prepare('INSERT INTO auth_attempts VALUES(?,?)').run(key,slot);db.exec('COMMIT');return slot}catch(error){db.exec('ROLLBACK');throw error}}
function inviteMatches(value,secret){const a=createHash('sha256').update(value).digest(),b=createHash('sha256').update(secret).digest();return timingSafeEqual(a,b)}
function cookie(raw,maxAge=28800){const secure=process.env.COOKIE_SECURE!=='false';return `${cookieName}=${raw}; HttpOnly; ${secure?'Secure; ':''}SameSite=Strict; Path=/; Max-Age=${maxAge}`}
function envelope(row){return{id:row.id,type:row.type,version:row.version,iv:row.iv,ciphertext:row.ciphertext,...(Number.isSafeInteger(row.created_at)?{createdAt:row.created_at}:{}),...(Number.isSafeInteger(row.revision)?{revision:row.revision}:{})}}
function attachment(row){return{id:row.id,metadata:{version:1,iv:row.metadata_iv,ciphertext:row.metadata_ciphertext},ciphertextSize:row.ciphertext_size,createdAt:row.created_at,updatedAt:row.updated_at,revision:row.revision}}
function nextRevision(userId,resourceType,id){const row=db.prepare('SELECT last_revision FROM revision_tombstones WHERE user_id=? AND resource_type=? AND id=?').get(userId,resourceType,id);return row?row.last_revision+1:1}
function rememberRevision(userId,resourceType,id,revision){db.prepare('INSERT INTO revision_tombstones(user_id,resource_type,id,last_revision) VALUES(?,?,?,?) ON CONFLICT(user_id,resource_type,id) DO UPDATE SET last_revision=MAX(last_revision,excluded.last_revision)').run(userId,resourceType,id,revision)}
function rememberTableRevisions(userId,resourceType,table){for(const row of db.prepare(`SELECT id,revision FROM ${table} WHERE user_id=?`).all(userId))rememberRevision(userId,resourceType,row.id,row.revision)}
function beginResourceWrite(userId){db.exec('BEGIN IMMEDIATE');db.prepare('DELETE FROM backup_import_locks WHERE expires_at<=?').run(Date.now());if(db.prepare('SELECT 1 FROM backup_import_locks WHERE user_id=?').get(userId)){db.exec('ROLLBACK');return false}return true}
function resourceWrite(userId,operation){if(!beginResourceWrite(userId))throw Object.assign(new Error('backup_import_in_progress'),{status:409});try{const value=operation();db.exec('COMMIT');return value}catch(error){db.exec('ROLLBACK');throw error}}
function deleteWithRevision(userId,resourceType,table,id,revision){if(!beginResourceWrite(userId))return{changes:0,importLocked:true};try{const result=db.prepare(`DELETE FROM ${table} WHERE user_id=? AND id=? AND revision=?`).run(userId,id,revision);if(result.changes)rememberRevision(userId,resourceType,id,revision);db.exec('COMMIT');return result}catch(error){db.exec('ROLLBACK');throw error}}
const userDir=userId=>join(ATTACHMENTS_DIR,digest(userId));
function queueFileDeletion(userId,objectKey){db.prepare('INSERT INTO pending_file_deletions(object_key,user_id,created_at) VALUES(?,?,?) ON CONFLICT(object_key) DO NOTHING').run(objectKey,userId,Date.now())}
async function syncDirectory(path){const handle=await open(path,'r');try{await handle.sync()}finally{await handle.close()}}
async function cleanupPendingFileDeletion(limit=16){const rows=db.prepare('SELECT object_key,user_id FROM pending_file_deletions ORDER BY created_at LIMIT ?').all(limit);let cleaned=0;for(const row of rows){if(db.prepare('SELECT 1 FROM attachments WHERE object_key=?').get(row.object_key)){db.prepare('DELETE FROM pending_file_deletions WHERE object_key=?').run(row.object_key);cleaned++;continue}try{await unlink(join(userDir(row.user_id),row.object_key))}catch(error){if(error.code!=='ENOENT')continue}db.prepare('DELETE FROM pending_file_deletions WHERE object_key=?').run(row.object_key);cleaned++}return cleaned}
const shareObjectPath=objectKey=>join(SHARES_DIR,objectKey);
async function removeShareObjectFile(objectKey){try{await unlink(shareObjectPath(objectKey))}catch(error){if(error.code!=='ENOENT')return false}return true}
async function cleanupExpiredShares(){const now=Date.now(),shareCutoff=now-SHARE_REVOKE_GRACE,pendingCutoff=now-PENDING_SHARE_AGE;
 // package objects whose package is expired/revoked/stale-pending: delete files then rows
 const deadObjects=db.prepare("SELECT o.share_token_hash tokenHash,o.object_key objectKey FROM secure_share_objects o JOIN secure_share_packages p ON p.token_hash=o.share_token_hash WHERE p.expires_at<=? OR (p.revoked_at IS NOT NULL AND p.revoked_at<=?) OR (p.status='pending' AND p.created_at<=?)").all(now,shareCutoff,pendingCutoff);
 for(const row of deadObjects)await removeShareObjectFile(row.objectKey);
 db.prepare("DELETE FROM secure_share_packages WHERE expires_at<=? OR (revoked_at IS NOT NULL AND revoked_at<=?) OR (status='pending' AND created_at<=?)").run(now,shareCutoff,pendingCutoff);
 db.prepare('DELETE FROM secure_shares WHERE expires_at<=? OR (revoked_at IS NOT NULL AND revoked_at<=?)').run(now,shareCutoff);
 db.prepare('DELETE FROM secure_share_sessions WHERE expires_at<=?').run(now);
 // orphan object files (no matching row) — reconcile FS against DB
 let names=[];try{names=await readdir(SHARES_DIR)}catch(error){if(error.code!=='ENOENT')throw error}
 for(const name of names){const dir=join(SHARES_DIR,name);let inner=[];try{inner=await readdir(dir)}catch{continue}
  for(const file of inner){const key=`${name}/${file}`;if(!db.prepare('SELECT 1 FROM secure_share_objects WHERE object_key=? AND uploaded_at IS NOT NULL').get(key)){try{await unlink(join(dir,file))}catch{}}}
  try{await readdir(dir).then(rest=>rest.length===0&&rmdir(dir)).catch(()=>{})}catch{}}
 return deadObjects.length}
function activeShareCount(userId,now){return db.prepare("SELECT COUNT(*) c FROM secure_share_packages WHERE user_id=? AND revoked_at IS NULL AND expires_at>? AND status IN('pending','active')").get(userId,now).c+db.prepare('SELECT COUNT(*) c FROM secure_shares WHERE user_id=? AND revoked_at IS NULL AND expires_at>? AND view_count<max_views').get(userId,now).c}
function shareCookie(raw,maxAgeSec){const secure=process.env.COOKIE_SECURE!=='false';return `${SHARE_COOKIE}=${raw}; HttpOnly; ${secure?'Secure; ':''}SameSite=Strict; Path=/api/shares; Max-Age=${maxAgeSec}`}
function shareCookieValue(req){return (req.headers.cookie||'').split(';').map(v=>v.trim().split('=')).find(v=>v[0]===SHARE_COOKIE)?.[1]}
async function shareBinary(req,limit){const declared=Number(req.headers['content-length']);if(!Number.isSafeInteger(declared)||declared<1||declared>limit)throw Object.assign(new Error('too_large'),{status:413});let size=0,chunks=[];for await(const chunk of req){size+=chunk.length;if(size>limit)throw Object.assign(new Error('too_large'),{status:413});chunks.push(chunk)}if(size!==declared)throw Object.assign(new Error('invalid_length'),{status:400});return Buffer.concat(chunks)}
async function writeShareObject(objectKey,payload){const target=shareObjectPath(objectKey),dir=dirname(target);await mkdir(dir,{recursive:true});const tmp=join(dir,`.${randomBytes(8).toString('hex')}.tmp`);let handle;try{handle=await open(tmp,'wx',0o600);await handle.write(payload);await handle.sync();await handle.close();handle=null;await rename(tmp,target);await syncDirectory(dir)}catch(e){await handle?.close().catch(()=>{});await unlink(tmp).catch(()=>{});throw e}}
