function createPasskeySession(req,userId){const raw=randomBytes(32).toString('base64url'),csrfToken=randomBytes(24).toString('base64url'),sessionId=randomBytes(18).toString('base64url'),now=Date.now(),client=classifySessionClient(String(req.headers['user-agent']||'')),ip=normalizeSessionIp(clientIp(req));return{raw,csrfToken,sessionId,now,values:[digest(raw),userId,digest(csrfToken),now+SESSION_MS,sessionId,now,now,ip,client.device,client.browser,'passkey']}}
